<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_role('Entrenador');$pdo=dogvive_db();$uid=dogvive_user_id();$name=$_SESSION['dogvibe_user']['nombre']??'Entrenador';$q=$pdo->prepare("SELECT COUNT(*) FROM reserva WHERE id_entrenador=? AND Estado IN ('Pendiente','Confirmada') AND Fecha>=CURDATE()");$q->execute([$uid]);$upcoming=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(DISTINCT id_mascota) FROM reserva WHERE id_entrenador=? AND id_mascota IS NOT NULL');$q->execute([$uid]);$pets=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM mensaje WHERE id_destinatario=? AND Leido=0');$q->execute([$uid]);$messages=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT r.*,s.Nombre AS servicio,m.Nombre AS mascota,u.Nombre AS propietario,u.Apellido AS apellido FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio LEFT JOIN mascota m ON m.id_mascota=r.id_mascota LEFT JOIN usuario u ON u.id_usuario=r.id_usuario WHERE r.id_entrenador=? ORDER BY r.Fecha,r.Hora LIMIT 5");$q->execute([$uid]);$rows=$q->fetchAll();$q=$pdo->prepare('SELECT AVG(Calificacion) AS rating,COUNT(*) AS reviews FROM resena re JOIN reserva r ON r.id_reserva=re.id_reserva WHERE r.id_entrenador=?');$q->execute([$uid]);$rating=$q->fetch();start_app('Panel del entrenador','dashboard-entrenador'); ?>
<section class="trainer-dashboard page-wrap"><div class="trainer-hero-card"><div><span class="trainer-kicker">🎓 PANEL PROFESIONAL</span><h1>Hola, <?= e($name) ?> 👋</h1><p>Gestiona tu agenda, solicitudes y comunicación con propietarios.</p><div class="trainer-hero-actions"><?= btn('📅 Ver mi agenda',page_url('reservas'),'btn-primary') ?> <?= btn('💬 Revisar mensajes',page_url('mensajes'),'btn-secondary') ?></div></div><div class="trainer-hero-badge"><span>★</span><strong><?= $rating['rating']?number_format((float)$rating['rating'],1):'—' ?></strong><small><?= (int)($rating['reviews']??0) ?> reseñas</small></div></div><div class="grid grid-4 trainer-stats"><div class="card trainer-stat"><span>📅</span><strong><?= $upcoming ?></strong><small>Sesiones próximas</small></div><div class="card trainer-stat"><span>🐶</span><strong><?= $pets ?></strong><small>Mascotas atendidas</small></div><div class="card trainer-stat"><span>💬</span><strong><?= $messages ?></strong><small>Mensajes sin leer</small></div><div class="card trainer-stat"><span>⭐</span><strong><?= (int)($rating['reviews']??0) ?></strong><small>Reseñas recibidas</small></div></div><div class="trainer-content-grid"><div><div class="section-title-row"><h2 class="section-title">Agenda y solicitudes</h2><a href="<?= e(page_url('reservas')) ?>">Ver agenda →</a></div><?php if(!$rows): ?><div class="card"><p>No tienes solicitudes asignadas todavía.</p><p class="muted">Cuando un propietario te seleccione para un servicio, aparecerá aquí.</p></div><?php else: ?><div class="trainer-session-list"><?php foreach($rows as $r): ?><div class="card trainer-session"><div class="session-date"><b><?= e(date('d',strtotime((string)$r['Fecha']))) ?></b><small><?= e(strtoupper(date('M',strtotime((string)$r['Fecha'])))) ?></small></div><div class="grow"><strong><?= e((string)($r['mascota']??'Mascota')) ?> · <?= e((string)($r['servicio']??'Servicio')) ?></strong><small class="muted"><?= e(substr((string)$r['Hora'],0,5)) ?> · <?= e(trim(($r['propietario']??''). ' '.($r['apellido']??''))) ?></small><span class="trainer-client"><?= e((string)$r['Estado']) ?></span></div></div><?php endforeach; ?></div><?php endif; ?></div><aside><div class="card trainer-profile-card"><div class="trainer-avatar-big">🎓</div><span class="verified-badge"><?= e((string)($_SESSION['dogvibe_user']['rol']??'Entrenador')) ?></span><h3><?= e($name) ?></h3><p><?= e((string)($_SESSION['dogvibe_user']['especialidad']??'Especialidad no indicada')) ?></p><div class="trainer-profile-meta"><span><?= (int)($_SESSION['dogvibe_user']['experiencia']??0) ?> años</span><span><?= e((string)($_SESSION['dogvibe_user']['ciudad']??'')) ?></span></div><?= btn('Editar mi perfil',page_url('editar-perfil'),'btn-secondary full') ?></div><div class="card trainer-tip"><span>💡</span><div><strong>Consejo</strong><p>Mantén tu disponibilidad y tus datos profesionales actualizados.</p></div></div></aside></div></section><?php end_app();
